styles:
.doc {
  padding: 32px;
  max-width: 860px;
  background: var(--fs-color-bg);
  color: var(--fs-color-text-primary);
  font-family: 'Plus Jakarta Sans', system-ui, sans-serif;
  font-size: 13px;
}

section { margin-bottom: 52px; }

.section-header { margin-bottom: 16px; }

.section-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--fs-color-text-primary);
  margin: 0 0 6px;
  letter-spacing: -0.02em;
}

.section-desc {
  font-size: 12.5px;
  color: var(--fs-color-text-secondary);
  line-height: 1.6;
  margin: 0;
}

code {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 11px;
  color: var(--fs-color-primary);
  background: color-mix(in srgb, var(--fs-color-primary) 8%, var(--fs-color-surface));
  padding: 1px 5px;
  border-radius: 4px;
}

.sub-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fs-color-text-secondary);
  margin-bottom: 8px;
}

/* ── Code blocks ──────────────────────────────────────── */
.code-pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

@media (max-width: 640px) { .code-pair { grid-template-columns: 1fr; } }

.code-block {
  background: var(--fs-color-surface);
  border: 1px solid var(--fs-color-border);
  border-radius: var(--fs-radius-lg);
  padding: 14px 16px;
}

.code-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fs-color-text-secondary);
  margin-bottom: 8px;
}

pre {
  font-size: 11.5px;
  color: var(--fs-color-text-primary);
  font-family: 'JetBrains Mono', monospace;
  white-space: pre-wrap;
  margin: 0;
  line-height: 1.7;
}

/* ── Flex demos ───────────────────────────────────────── */
.flex-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 10px;
}

.demo-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.demo-preview {
  background: var(--fs-color-surface);
  border: 1px solid var(--fs-color-border);
  border-radius: var(--fs-radius-md);
  min-height: 60px;
  padding: 8px;
}

.demo-code {
  font-size: 10px;
}

.demo-label {
  font-size: 10.5px;
  color: var(--fs-color-text-secondary);
}

.dot {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--fs-color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}

/* ── Gap ──────────────────────────────────────────────── */
.gap-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.gap-row {
  display: flex;
  align-items: center;
  gap: 16px;
}

.gap-token { min-width: 64px; }

.chips {
  display: flex;
}

.chip {
  background: color-mix(in srgb, var(--fs-color-primary) 12%, transparent);
  color: var(--fs-color-primary);
  border-radius: 4px;
  padding: 4px 9px;
  font-size: 11px;
  font-weight: 600;
}

.gap-val {
  font-size: 11px;
  color: var(--fs-color-text-secondary);
}

/* ── Spacing ──────────────────────────────────────────── */
.sp-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 8px;
}

.sp-card {
  background: var(--fs-color-surface);
  border: 1px solid var(--fs-color-border);
  border-radius: var(--fs-radius-md);
  overflow: hidden;
}

.sp-tag {
  font-size: 10px;
  font-weight: 600;
  color: var(--fs-color-text-secondary);
  padding: 5px 8px;
  background: var(--fs-color-surface-alt);
  border-bottom: 1px solid var(--fs-color-border);
}

.sp-box {
  background: var(--fs-color-bg);
}

.sp-inner {
  background: color-mix(in srgb, var(--fs-color-primary) 14%, transparent);
  color: var(--fs-color-primary);
  font-size: 11px;
  font-weight: 600;
  text-align: center;
  border-radius: 3px;
  padding: 5px;
}

.margin-outer {
  padding: 4px;
  background: color-mix(in srgb, var(--fs-color-warning) 8%, var(--fs-color-bg));
  border: 1px dashed color-mix(in srgb, var(--fs-color-warning) 30%, transparent);
  border-radius: 3px;
  margin: 4px;
}

.margin-inner {
  background: var(--fs-color-surface);
  border: 1px solid var(--fs-color-border);
  border-radius: 4px;
  font-size: 11px;
  color: var(--fs-color-text-secondary);
  padding: 5px 8px;
  text-align: center;
}

/* ── Typography ───────────────────────────────────────── */
.type-demos {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 20px;
}

.type-row {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 8px 12px;
  border-radius: var(--fs-radius-md);
  transition: background 120ms ease;

  &:hover { background: var(--fs-color-surface-alt); }
}

.type-sample {
  color: var(--fs-color-text-primary);
  min-width: 200px;
  flex-shrink: 0;
}

.type-code {
  min-width: 180px;
  flex-shrink: 0;
}

.type-desc {
  font-size: 11px;
  color: var(--fs-color-text-secondary);
}

.size-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.size-row {
  display: flex;
  align-items: baseline;
  gap: 16px;
  padding: 6px 10px;
  border-radius: var(--fs-radius-sm);

  &:hover { background: var(--fs-color-surface-alt); }
}

.size-token { min-width: 120px; flex-shrink: 0; }

.size-preview {
  color: var(--fs-color-text-primary);
  min-width: 120px;
}

.size-val {
  font-size: 11px;
  color: var(--fs-color-text-secondary);
}

/* ── Responsive ───────────────────────────────────────── */
.bp-table {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.bp-row {
  display: flex;
  align-items: center;
  gap: 14px;
}

.bp-name { min-width: 40px; }

.bp-bar-wrap {
  flex: 1;
  height: 10px;
  background: var(--fs-color-surface-alt);
  border-radius: 3px;
  overflow: hidden;
}

.bp-bar {
  height: 100%;
  background: var(--fs-color-primary);
  opacity: 0.4;
  border-radius: 3px;
}

.bp-val {
  font-size: 11px;
  color: var(--fs-color-text-secondary);
  min-width: 48px;
  text-align: right;
}

/* ── Visual ───────────────────────────────────────────── */
.visual-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: flex-end;
}

.visual-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.vis-label {
  font-size: 11px;
  color: var(--fs-color-text-secondary);
}

.vis-code {
  font-size: 10px;
}

.vis-card {
  width: 120px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--fs-color-surface);
  border: 1px solid var(--fs-color-border);
  border-radius: var(--fs-radius-lg);
  transition: border-color 150ms ease;

  &:hover { border-color: var(--fs-color-border-strong); }
}

.vis-glass {
  width: 120px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--fs-color-text-primary) 5%, transparent);
  border: 1px solid color-mix(in srgb, var(--fs-color-text-primary) 10%, transparent);
  border-radius: var(--fs-radius-lg);
  backdrop-filter: blur(8px);
}

.vis-divider {
  width: 160px;
  height: 1px;
  background: var(--fs-color-border);
  margin: 24px 0;
}

.vis-btn-reset {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font-family: inherit;
  color: var(--fs-color-primary);
  font-size: 13px;
}

/* Reproduce el mixin focus-ring: el anillo interno usa el fondo del tema,
   así que se lee tanto en light como en dark. */
.vis-btn-focus {
  background: var(--fs-color-surface);
  border: 1px solid var(--fs-color-border);
  border-radius: var(--fs-radius-md);
  padding: 7px 12px;
  cursor: pointer;
  font-family: inherit;
  font-size: 12.5px;
  color: var(--fs-color-text-primary);
}

.vis-btn-focus:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--fs-color-bg),
              0 0 0 4px var(--fs-color-primary);
}

.radii-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: flex-end;
}

.radius-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.radius-box {
  width: 48px;
  height: 48px;
  background: var(--fs-color-surface);
  border: 1.5px solid var(--fs-color-primary);
}

.radius-code { font-size: 10px; }

/* ── Badge helpers ────────────────────────────────────── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.bv-primary, .bv-secondary, .bv-danger, .bv-success, .bo-primary, .bo-danger {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 9999px;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.5;
}

.bv-primary   { background: color-mix(in srgb, var(--fs-color-primary) 12%, transparent); color: var(--fs-color-primary); border: 1px solid color-mix(in srgb, var(--fs-color-primary) 28%, transparent); }
.bv-secondary { background: rgba(14,165,233,0.12); color: #0284c7; border: 1px solid rgba(14,165,233,0.28); }
.bv-danger    { background: color-mix(in srgb, var(--fs-color-error) 12%, transparent); color: var(--fs-color-error); border: 1px solid color-mix(in srgb, var(--fs-color-error) 28%, transparent); }
.bv-success   { background: color-mix(in srgb, var(--fs-color-success) 12%, transparent); color: var(--fs-color-success); border: 1px solid color-mix(in srgb, var(--fs-color-success) 28%, transparent); }
.bo-primary   { background: transparent; color: var(--fs-color-primary); border: 1px solid var(--fs-color-primary); }
.bo-danger    { background: transparent; color: var(--fs-color-error); border: 1px solid var(--fs-color-error); }

