.doc {
  padding: 32px;
  max-width: 860px;
  background: var(--fs-color-bg);
  color: var(--fs-color-text-primary);
  font-family: 'Plus Jakarta Sans', system-ui, sans-serif;
  font-size: 13px;
}

section { margin-bottom: 52px; }

.section-header { margin-bottom: 20px; }

.section-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--fs-color-text-primary);
  margin: 0 0 6px;
  letter-spacing: -0.02em;
}

.section-desc {
  font-size: 12.5px;
  color: var(--fs-color-text-secondary);
  line-height: 1.6;
  margin: 0;
}

code {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 11px;
  color: var(--fs-color-primary);
  background: color-mix(in srgb, var(--fs-color-primary) 8%, var(--fs-color-surface));
  padding: 1px 5px;
  border-radius: 4px;
}

/* ── Brand scales ─────────────────────────────────────── */
.scale-block { margin-bottom: 24px; }

.scale-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
}

.scale-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--fs-color-text-primary);
  text-transform: capitalize;
}

.scale-hex {
  font-size: 11px;
  opacity: 0.7;
}

.scale-row {
  display: flex;
  border-radius: var(--fs-radius-lg);
  overflow: hidden;
  border: 1px solid var(--fs-color-border);
}

.stop {
  flex: 1;
  height: 52px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding-bottom: 5px;
}

.stop-num {
  font-size: 9px;
  font-weight: 700;
  color: rgba(255,255,255,0.55);
  mix-blend-mode: difference;
  font-family: 'JetBrains Mono', monospace;
}

.alias-row {
  display: flex;
  gap: 4px;
  margin-top: 6px;
}

.alias-chip {
  flex: 1;
  height: 22px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.alias-name {
  font-size: 8.5px;
  font-weight: 700;
  color: rgba(255,255,255,0.6);
  mix-blend-mode: difference;
  font-family: 'JetBrains Mono', monospace;
}

/* ── Semantic brand ───────────────────────────────────── */
.semantic-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.sem-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.sem-swatch {
  width: 80px;
  height: 36px;
  border-radius: var(--fs-radius-md) var(--fs-radius-md) 0 0;
  border: 1px solid var(--fs-color-border);
  border-bottom: none;
}

.sem-muted {
  width: 80px;
  height: 24px;
  border-radius: 0 0 var(--fs-radius-md) var(--fs-radius-md);
  border: 1px solid var(--fs-color-border);
  border-top: none;
}

.sem-name {
  font-size: 11px;
  text-align: center;
  display: block;
  margin-top: 2px;
}

/* ── Alias table ──────────────────────────────────────── */
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

th {
  text-align: left;
  padding: 8px 12px;
  background: var(--fs-color-surface-alt);
  color: var(--fs-color-text-secondary);
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  border-bottom: 1px solid var(--fs-color-border);
}

td {
  padding: 9px 12px;
  border-bottom: 1px solid var(--fs-color-border);
  color: var(--fs-color-text-primary);
  vertical-align: middle;
}

.stop-badge {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
  color: rgba(255,255,255,0.7);
  mix-blend-mode: difference;
  background-color: inherit;
}

.usage-cell { color: var(--fs-color-text-secondary); font-size: 12px; }

.val-code {
  color: var(--fs-color-text-secondary);
  background: var(--fs-color-surface-alt);
}

/* ── Semantic UI tokens ───────────────────────────────── */
.ui-group { margin-bottom: 20px; }

.ui-group-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fs-color-text-secondary);
  margin-bottom: 8px;
}

.ui-tokens-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ui-token {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  width: 96px;
}

.ui-swatch {
  width: 96px;
  height: 44px;
  border-radius: var(--fs-radius-md);
  border: 1px solid var(--fs-color-border);
}

.ui-token-name {
  font-size: 9.5px;
  text-align: center;
  word-break: break-all;
  line-height: 1.3;
}

.ui-token-desc {
  font-size: 10px;
  color: var(--fs-color-text-secondary);
  text-align: center;
}

/* ── Radii ────────────────────────────────────────────── */
.radii-row {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  align-items: flex-end;
}

.radius-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.radius-box {
  width: 52px;
  height: 52px;
  background: var(--fs-color-surface);
  border: 1.5px solid var(--fs-color-primary);
}

.radius-token {
  font-size: 10px;
  text-align: center;
}

.radius-val {
  font-size: 10px;
  color: var(--fs-color-text-secondary);
}

/* ── Spacing ──────────────────────────────────────────── */
.space-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.space-row {
  display: flex;
  align-items: center;
  gap: 14px;
}

.space-token { min-width: 120px; flex-shrink: 0; }

.space-bar-wrap {
  flex: 1;
  height: 16px;
  background: var(--fs-color-surface-alt);
  border-radius: 3px;
  overflow: hidden;
}

.space-bar {
  height: 100%;
  background: var(--fs-color-primary);
  opacity: 0.35;
  border-radius: 3px;
  min-width: 4px;
}

.space-val {
  font-size: 11px;
  color: var(--fs-color-text-secondary);
  min-width: 32px;
  text-align: right;
}

/* ── Shadows ──────────────────────────────────────────── */
.shadow-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: flex-end;
}

.shadow-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 16px 20px;
  background: var(--fs-color-surface);
  border-radius: var(--fs-radius-lg);
  border: 1px solid var(--fs-color-border);
  min-width: 120px;
}

.shadow-item--pop {
  border-width: 0;
}

.shadow-tag {
  font-size: 10.5px;
  color: var(--fs-color-text-secondary);
}

/* ── Typography ───────────────────────────────────────── */
.type-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.type-row {
  display: flex;
  align-items: baseline;
  gap: 16px;
  padding: 7px 12px;
  border-radius: var(--fs-radius-md);
  transition: background 120ms ease;

  &:hover { background: var(--fs-color-surface-alt); }
}

.type-preview {
  font-family: inherit;
  color: var(--fs-color-text-primary);
  min-width: 160px;
  flex-shrink: 0;
}

.type-token { min-width: 160px; flex-shrink: 0; }

.type-meta {
  font-size: 11px;
  color: var(--fs-color-text-secondary);
}

/* ── Z-index ──────────────────────────────────────────── */
.z-row {
  display: flex;
  gap: 12px;
  align-items: flex-end;
}

.z-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.z-bar {
  width: 40px;
  background: color-mix(in srgb, var(--fs-color-primary) 30%, transparent);
  border-radius: var(--fs-radius-sm) var(--fs-radius-sm) 0 0;
  border: 1px solid color-mix(in srgb, var(--fs-color-primary) 40%, transparent);
  border-bottom: none;
}

.z-token {
  font-size: 9px;
  text-align: center;
  line-height: 1.4;
}

.z-val {
  font-size: 11px;
  font-weight: 700;
  color: var(--fs-color-text-secondary);
}

